        {
          "text": "Comparison of current AI stack to past tech stacks (REST, JSON, Microservices, Docker).",
          "evidence": [10]
        },
        {
          "text": "Observation that search for candidates by keywords is less realistic than before.",
          "evidence": [13]
        },
        {
          "text": "Statement that answer quality is often proportional to question quality and system knowledge.",
          "evidence": [24, 25]
        }
      ]
